entries[189624] = { ["name"] = "10.0 Raid Template - Generic - Neck", ["text"] = "Binds when picked up\nNeck\n+100 Stamina\n+ 85 Haste\n+ 246 Mastery\nUse: Ensorcell the mind of a Beast found outdoors in the Shadowlands. If affected, your target will assist you for 5 min. (1 Hour Cooldown)\nSell Price:" }
entries[189625] = { ["name"] = "10.0 Raid Template - Melee DPS - Trinket", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+112 [Agility or Strength]\nUse: Become the Skulking Predator for 10 sec, gaining 278 Speed and pouncing on the next enemy to come within 8 yds, dealing 19822 Physical damage. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[189626] = { ["name"] = "10.0 Raid Template - Tank - Trinket", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+112 [Agility or Strength]\nUse: Form a Huntsman's Bond with a target ally for 30 sec. 25% of damage you suffer will be redirected to your bonded ally, up to [ 58281 * (1 + Versatility)] total damage redirected. (2 Min Cooldown)\nSell Price:" }
entries[189627] = { ["name"] = "10.0 Raid Template - Int DPS - Trinket", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+112 Intellect\nUse: Activate Soul Igniter, sacrificing up to 11037 health over 15 sec to empower Blazing Surge.\n\nReactivate to cast Blazing Surge, dealing [ 7884 * (1 + Versatility)] Fire damage split between enemies in a 40 yd cone, plus up to 40% additional damage, based on how long Soul Igniter was active.\n\nDamage is increased per enemy struck, up to 5 enemies. (1 min Cooldown)\nSell Price:" }
entries[189628] = { ["name"] = "10.0 Raid Template - Healer - Trinket", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+112 Intellect\nUse: Infuse your ally with a tuft of phoenix plumes, healing them for [ 26603 * (1 + Versatility)] after 6 sec, increased by up to 25% based on your target's missing health. If your ally suffers lethal damage, this effect triggers instantly. (2 Min Cooldown)\nSell Price:" }
entries[189629] = { ["name"] = "10.0 Raid Template - STR - Trinket", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+112 Strength\nEquip: Your damaging abilities have a high chance to deal 595 Physical damage, healing you for 300% of the damage dealt. If this effect overheals, deal [ 501 * 5 * (1 + Versatility)] Physical damage split between nearby enemies over 15 sec, but suppress the lifesteal effect.\n\nDamage increased per enemy struck, up to 5 enemies.\nSell Price:" }
entries[189630] = { ["name"] = "10.0 Raid Template - Omni - Trinket", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+112 [Agility or Strength or Intellect]\nUse: Four dance partners appear in a random pattern around you. Moving to each grants you 163 Haste and 91 Speed for 20 sec, stacking. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[189631] = { ["name"] = "10.0 Raid Template - Physical DPS - Trinket", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+112 [Agility or Strength]\nUse: Your next 5 damaging abilities inflict Shattered Psyche, dealing 3330 Shadow damage and increasing the target's damage taken from Shattered Psyche by 1% for 5 sec, stacking up to 25 times. (1.5s cooldown) (2 Min Cooldown)\nSell Price:" }
entries[189632] = { ["name"] = "10.0 Raid Template - AGI - Trinket", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+112 Agility\nEquip: While you have a greater health percentage than your target, your abilities have a very high chance to deal [ 925 * (1 + Versatility)] Physical damage.\n\nWhile you have a lower health percentage than your target, your abilities have a very high chance to heal you for [ 1263 * (1 + Versatility)].\nSell Price:" }
entries[189633] = { ["name"] = "10.0 Raid Template - INT - Trinket", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+112 Intellect\nEquip: Join the Crimson Chorus. Every minute, your Critical Strike swells by ( 158 * 3) over 30 sec. before returning to normal. This effect is increased by 5% for each member of the Crimson Chorus in your party.\nSell Price:" }
