entries[190580] = { ["name"] = "Heartbond Lupine", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"From the moment of its creation, this packless lupine has held nothing more than deepest affection and loyalty towards you.\"\nProfession:\nProtoform Synthesis" }
