entries[190657] = { ["name"] = "Resonant Rage Fluidic Spheroid", ["text"] = "Conjured Item\nBinds when picked up\nDuration: 1 hour\nUse: When Pocopoc possesses a Coreless Vombata, it has a chance to cast an 8 sec Bloodlust on kill.\nThis effect will last for 15 min. Only works in Shadowlands outdoor areas or Oribos.\nSell Price:" }
